#include <iostream>
#include <string>
using namespace std;

unsigned long djb2(const string& s) {
    unsigned long hash = 5381;
    for (char c : s) hash = ((hash << 5) + hash) + c;
    return hash;
}

int main() {
    cout << "hello: " << djb2("hello") << endl;
    cout << "world: " << djb2("world") << endl;
    cout << "hello: " << djb2("hello") << endl;
    return 0;
}
